        public const float CladdingThickness = 0.08f;
        public const float SpandrelProtrusion = 0.06f;
        public const float CorniceOverhang = 0.18f;
        public const float RoofDeckThickness = 0.28f;
        public const float ParapetHeight = 0.42f;

        // The tower camera sits on negative Z and looks toward positive Z,
        // so smaller Z values are closer to the camera.
        private const float EarthTileZ = 0.44f;
        private const float EarthDetailZ = 0.42f;
        private const float ExcavationZ = 0.38f;
        private const float LairFloorZ = 0.34f;

        private Transform _parent;
        private Material _worldMaterial;
        private Material _coneMaterial;
        private MaterialPropertyBlock _colorBlock;

        private Transform _root;
        private Transform _leftFacadeRoot;
        private Transform _rightFacadeRoot;
        private Transform _rooflineRoot;
        private Transform _fixturesRoot;
        private Transform _terracesRoot;
        private Transform _volumetricLightRoot;
        private Transform _groundRoot;

        private readonly List<GameObject> _leftWallSlices = new List<GameObject>();
        private readonly List<GameObject> _rightWallSlices = new List<GameObject>();
        private readonly List<GameObject> _leftSpandrels = new List<GameObject>();
        private readonly List<GameObject> _rightSpandrels = new List<GameObject>();
        private readonly List<GameObject> _terraceObjects = new List<GameObject>();
        private readonly List<GameObject> _roofObjects = new List<GameObject>();

        private readonly List<GameObject> _leftWindowFrames = new List<GameObject>();
        private readonly List<GameObject> _leftWindowGlasses = new List<GameObject>();
        private readonly List<GameObject> _leftWindowSills = new List<GameObject>();
        private readonly List<GameObject> _rightWindowFrames = new List<GameObject>();
        private readonly List<GameObject> _rightWindowGlasses = new List<GameObject>();
        private readonly List<GameObject> _rightWindowSills = new List<GameObject>();
        private readonly List<GameObject> _volumetricCones = new List<GameObject>();
        private readonly List<Mesh> _coneMeshes = new List<Mesh>();
        private readonly List<WindowLightingEntry> _windowLightingEntries = new List<WindowLightingEntry>();
        private readonly Dictionary<UndergroundCell, GameObject> _excavationViews = new Dictionary<UndergroundCell, GameObject>();
        private readonly Dictionary<UndergroundCell, GameObject> _lairFloorViews = new Dictionary<UndergroundCell, GameObject>();
        private readonly Dictionary<UndergroundCell, GameObject> _corridorViews = new Dictionary<UndergroundCell, GameObject>();
        private readonly Dictionary<UndergroundCell, GameObject> _shaftViews = new Dictionary<UndergroundCell, GameObject>();
        private readonly Dictionary<int, GameObject> _undergroundRoomViews = new Dictionary<int, GameObject>();
        private readonly Dictionary<int, NpcSkeletalHierarchy> _undergroundCrewViews = new Dictionary<int, NpcSkeletalHierarchy>();
        public IReadOnlyCollection<int> VisibleUndergroundCrewResidentIds => _undergroundCrewViews.Keys;
        private GameObject _accessCoreView;
        private int _renderedUndergroundRevision = -1;

